"use client";
/**
 * <LegendaryBackground> — drop inside any hero <section> (which must be `position: relative` +
 * `isolation: isolate` + `overflow: hidden`). Renders the art-directed static image first (LCP-safe),
 * then fades in the live animated layer (unless reduced motion / no WebGL / offscreen).
 *
 * Generated by the legendary-backgrounds skill. Paths point at files the skill exported to /public.
 */
import { useEffect, useRef } from "react";
import { mountLegendaryBackground } from "__LIVE_IMPORT__";
import recipe from "./__NAME__.recipe.json";

const BASE = "__PUBLIC_URL__/__NAME__";

export function __COMPONENT__({ live = true, className = "" }: { live?: boolean; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!live || !ref.current) return;
    const img = ref.current.querySelector("img");
    return mountLegendaryBackground(ref.current, { recipe, image: img?.currentSrc || `${BASE}-desktop-1920.webp` });
  }, [live]);

  return (
    <div
      ref={ref}
      aria-hidden="true"
      className={className}
      style={{
        position: "absolute", inset: 0, zIndex: -1, overflow: "hidden",
        backgroundColor: "__PAGE_BG__",
        backgroundImage: "url(__BLUR_DATA_URL__)", backgroundSize: "cover", backgroundPosition: "center",
      }}
    >
      <picture>
        <source media="(max-width: 767px)" type="image/avif" srcSet="__MOBILE_AVIF_SRCSET__" sizes="100vw" />
        <source media="(max-width: 767px)" type="image/webp" srcSet="__MOBILE_WEBP_SRCSET__" sizes="100vw" />
        <source type="image/avif" srcSet="__DESKTOP_AVIF_SRCSET__" sizes="100vw" />
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={`${BASE}-desktop-1920.webp`}
          srcSet="__DESKTOP_WEBP_SRCSET__"
          sizes="100vw"
          alt=""
          fetchPriority="high"
          decoding="async"
          style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover",
                   objectPosition: "__OBJECT_POSITION__" }}
        />
      </picture>
    </div>
  );
}
